        for c in range(w - p):
            for r in range(h):
                a = grid[r][c]
                b = grid[r][c + p]
                if a != 0 and b != 0 and a != b:
                    return False
        return True

    pr = next(p for p in range(1, h + 1) if valid_row_period(p))
    pc = next(p for p in range(1, w + 1) if valid_col_period(p))

    tile = {}
